<?php
if(!defined('ABSPATH'))exit;
final class MGD_WordPress_MCP_Admin{
 private static $instance=null;public static function instance(){if(null===self::$instance)self::$instance=new self();return self::$instance;}
 private function __construct(){add_action('admin_menu',array($this,'menu'));add_action('admin_init',array($this,'settings'));add_action('admin_enqueue_scripts',array($this,'assets'));add_filter('plugin_action_links_'.MGD_WPMCP_BASENAME,array($this,'action_links'));add_filter('plugin_row_meta',array($this,'row_meta'),10,2);}
 public function menu(){add_management_page('MGD WordPress MCP','MGD WordPress MCP','manage_options','mgd-wordpress-mcp',array($this,'render'));}
 public function settings(){register_setting('mgd_wordpress_mcp',MGD_WordPress_MCP::OPTION_SETTINGS,array('type'=>'array','sanitize_callback'=>array($this,'sanitize'),'default'=>MGD_WordPress_MCP::defaults()));}
 public function sanitize($input){$old=MGD_WordPress_MCP::get_settings();$clean=$old;foreach(array('writes_enabled','maintenance_enabled','divi_writes_enabled','media_imports_enabled','github_updates','audit_enabled') as $key)$clean[$key]=!empty($input[$key]);$clean['max_upload_mb']=max(1,min(64,absint($input['max_upload_mb']??($old['max_upload_mb']??8))));return $clean;}
 public function assets($hook){if('tools_page_mgd-wordpress-mcp'!==$hook&&'plugins.php'!==$hook)return;wp_enqueue_style('mgd-wordpress-mcp-admin',MGD_WPMCP_URL.'assets/admin.css',array(),MGD_WPMCP_VERSION);}
 public function action_links($links){array_unshift($links,'<a href="'.esc_url(admin_url('tools.php?page=mgd-wordpress-mcp&tab=wizard')).'">Einrichten</a>');return $links;}
 public function row_meta($links,$file){if(MGD_WPMCP_BASENAME!==$file)return $links;$details=add_query_arg(array('tab'=>'plugin-information','plugin'=>'mgd-wordpress-mcp','TB_iframe'=>'true','width'=>'772','height'=>'650'),self_admin_url('plugin-install.php'));$links[]='<a href="'.esc_url($details).'" class="thickbox open-plugin-details-modal">Details ansehen</a>';$links[]='<a href="'.esc_url(admin_url('tools.php?page=mgd-wordpress-mcp&tab=about')).'">Über & Impressum</a>';$links[]='<a href="https://Michael-Gahn.de" target="_blank" rel="noopener noreferrer">Michael-Gahn.de</a>';$links[]='<a href="https://github.com/MichaelGahnDESIGN/MGD_WordPress-MCP" target="_blank" rel="noopener noreferrer">GitHub</a>';return $links;}
 private function nav($tab,$base){$tabs=array('status'=>'Übersicht','start-prompt'=>'Start-Prompt','wizard'=>'Einrichtungs-Assistent','settings'=>'Sicherheit & Freigaben','help'=>'Verbindung','audit'=>'Audit-Log','about'=>'Über das Plugin');echo '<nav class="nav-tab-wrapper">';foreach($tabs as $k=>$label)echo '<a class="nav-tab '.($k===$tab?'nav-tab-active':'').'" href="'.esc_url(add_query_arg('tab',$k,$base)).'">'.esc_html($label).'</a>';echo '</nav>';}
 private function checkbox($key,$label,$desc,$settings){?><label class="mgd-wpmcp-toggle"><input type="checkbox" name="<?php echo esc_attr(MGD_WordPress_MCP::OPTION_SETTINGS);?>[<?php echo esc_attr($key);?>]" value="1" <?php checked(!empty($settings[$key]));?>><span><strong><?php echo esc_html($label);?></strong><small><?php echo esc_html($desc);?></small></span></label><?php}
 private function start_prompt(){ $endpoint=MGD_WordPress_MCP::adapter_endpoint_url();$profile=MGD_WordPress_MCP_Security::profile();$labels=array('read_only'=>'Nur lesen','content_editor'=>'Inhalte bearbeiten','admin'=>'Administration');$prompt="Du arbeitest mit einer WordPress-Website, auf der MGD WordPress MCP installiert ist.\n\nProjekt und aktuelle Dokumentation:\nhttps://github.com/MichaelGahnDESIGN/MGD_WordPress-MCP\n\nLies vor Beginn die aktuelle README, Dokumentation und relevante Release Notes im Repository, damit du nicht von veralteten Fähigkeiten oder Endpoints ausgehst.\n\nMCP-Endpunkt dieser Website:\n".$endpoint."\n\nAktuelles Sicherheitsprofil:\n".($labels[$profile]??$profile)."\n\nArbeitsregeln:\n1. Prüfe zuerst die verfügbaren MCP-Tools und den Website-Status.\n2. Respektiere WordPress-Capabilities und alle im Plugin gesetzten Freigaben.\n3. Führe keine destruktiven oder administrativen Aktionen ohne ausdrücklichen Auftrag aus.\n4. Verwende bei Divi 5 nach Möglichkeit den MGD Divi 5 Dev Skill und sichere bestehende Inhalte vor größeren Änderungen.\n5. Gib niemals Application Passwords, Tokens oder andere Secrets in Logs, Dateien, GitHub oder öffentliche Ausgaben aus.\n6. Wenn eine gewünschte Aktion nicht freigegeben oder nicht als Tool verfügbar ist, erkläre konkret was fehlt, statt Schutzmechanismen zu umgehen.\n\nMein Auftrag für diese Sitzung:\n[HIER BESCHREIBEN, WAS DER AGENT AUF DER WEBSITE MACHEN SOLL]";?><section class="mgd-wpmcp-card"><div class="mgd-wpmcp-section-head"><span class="mgd-wpmcp-step">AI</span><div><h2>Start-Prompt für deinen KI-Agenten</h2><p>Kopiere diesen Text am Anfang einer neuen Chat-, Codex- oder Claude-Code-Sitzung. Der Agent bekommt damit Projektkontext, Repository, Endpoint und Sicherheitsregeln.</p></div></div><textarea id="mgd-start-prompt" class="large-text code" rows="22" readonly><?php echo esc_textarea($prompt);?></textarea><p><button type="button" class="button button-primary" onclick="navigator.clipboard.writeText(document.getElementById('mgd-start-prompt').value).then(()=>{this.textContent='✓ Kopiert';setTimeout(()=>this.textContent='Start-Prompt kopieren',1800);})">Start-Prompt kopieren</button> <a class="button" target="_blank" rel="noopener" href="https://github.com/MichaelGahnDESIGN/MGD_WordPress-MCP">Aktuellen Stand auf GitHub ansehen</a></p><p class="description">Der Prompt enthält keine Zugangsdaten. Ergänze unten nur deinen konkreten Auftrag.</p></section><?php }
 public function render(){if(!current_user_can('manage_options'))return;$settings=MGD_WordPress_MCP::get_settings();$tab=sanitize_key(wp_unslash($_GET['tab']??'status'));$base=admin_url('tools.php?page=mgd-wordpress-mcp');$env=MGD_WordPress_MCP_Environment::summary();?><div class="wrap mgd-wpmcp-wrap"><header class="mgd-wpmcp-hero"><div class="mgd-wpmcp-kicker">WORDPRESS MEETS AI · MICHAEL GAHN DESIGN</div><h1>MGD WordPress MCP</h1><p>Die sichere Verbindung zwischen deiner WordPress-Website und KI-Agenten wie Claude Code, Codex und anderen MCP-Clients.</p><div class="mgd-wpmcp-badges"><span class="mgd-wpmcp-badge is-red">v<?php echo esc_html(MGD_WPMCP_VERSION);?></span><span class="mgd-wpmcp-badge is-ok">Aktiv</span><span class="mgd-wpmcp-badge">WordPress 6.9+</span></div></header><?php $this->nav($tab,$base);
 if('start-prompt'===$tab){$this->start_prompt();}
 elseif('wizard'===$tab){MGD_WordPress_MCP_Wizard::render();}
 elseif('settings'===$tab){?><form method="post" action="options.php" class="mgd-wpmcp-card"><?php settings_fields('mgd_wordpress_mcp');?><h2>Sicherheit & Freigaben</h2><p>Die Profile werden bequem im Einrichtungs-Assistenten gewählt. Hier kannst du die automatisch gesetzten Rechte anschließend fein anpassen.</p><p><a class="button button-primary" href="<?php echo esc_url(admin_url('tools.php?page=mgd-wordpress-mcp&tab=wizard#mgd-security-profiles'));?>">Sicherheitsprofil wählen</a></p><?php $this->checkbox('writes_enabled','Schreibzugriff erlauben','Beiträge, Seiten, Medien und SEO-Daten erstellen oder ändern.',$settings);$this->checkbox('divi_writes_enabled','Divi-5-Schreibzugriff erlauben','Divi-Inhalte ändern.',$settings);$this->checkbox('media_imports_enabled','Externe Medienimporte erlauben','Dateien von ausdrücklich angegebenen externen URLs importieren.',$settings);$this->checkbox('maintenance_enabled','Wartung und Updates erlauben','Backups und Einzelupdates nach zusätzlicher Bestätigung.',$settings);$this->checkbox('audit_enabled','Audit-Log aktivieren','Technische MCP-Aktionen lokal protokollieren.',$settings);$this->checkbox('github_updates','Plugin-Updates über GitHub prüfen','Kontaktiert GitHub ausschließlich zur Versionsprüfung.',$settings);submit_button();?></form><?php}
 elseif('help'===$tab){$doctor=MGD_WordPress_MCP_Doctor::summary();?><section class="mgd-wpmcp-card"><h2>Connection Doctor</h2><p><strong><?php echo esc_html($doctor['passed'].' von '.$doctor['total'].' Prüfungen erfolgreich'); ?></strong></p><div class="mgd-wpmcp-ready-grid"><?php foreach($doctor['checks'] as $check):?><div class="mgd-wpmcp-ready-item <?php echo $check['status']==='pass'?'is-ok':'is-warn';?>"><span class="mgd-wpmcp-ready-dot"><?php echo $check['status']==='pass'?'✓':'!';?></span><span><strong><?php echo esc_html($check['label']);?></strong><small><?php echo esc_html($check['detail']);?></small></span></div><?php endforeach;?></div><h3>MCP-Endpunkt</h3><div class="mgd-wpmcp-endpoint"><code><?php echo esc_html(MGD_WordPress_MCP::adapter_endpoint_url());?></code></div><p><a class="button button-primary" href="<?php echo esc_url(admin_url('profile.php#application-passwords-section'));?>">Application Password erstellen</a></p></section><?php}
 elseif('audit'===$tab){$entries=MGD_WordPress_MCP_Audit::latest(100);?><section class="mgd-wpmcp-card"><h2>Audit-Log</h2><div class="mgd-wpmcp-table-wrap"><table class="widefat striped"><thead><tr><th>Zeit</th><th>Benutzer</th><th>Ability</th><th>Risiko</th><th>Status</th><th>Zusammenfassung</th></tr></thead><tbody><?php if(!$entries)echo '<tr><td colspan="6">Noch keine Einträge.</td></tr>';foreach($entries as $e)echo '<tr><td>'.esc_html($e['created_at']).'</td><td>'.esc_html($e['user_id']).'</td><td><code>'.esc_html($e['ability']).'</code></td><td>'.esc_html($e['risk']).'</td><td>'.($e['success']?'✓':'✕').'</td><td>'.esc_html($e['summary']).'</td></tr>';?></tbody></table></div></section><?php}
 elseif('about'===$tab){?><section class="mgd-wpmcp-card"><h2>Über MGD WordPress MCP</h2><p>Kostenloses Open-Source-Projekt von Michael Gahn DESIGN.</p><h3>Privacy by Default</h3><p>Keine externen Fonts, Icon-CDNs, JavaScript-CDNs oder Telemetrie in der Admin-Oberfläche.</p><h3>Impressum gemäß § 5 DDG</h3><p><strong>Michael Gahn DESIGN</strong><br>Inhaber: Michael Gahn<br>Dr.-Theodor-Brugsch-Str. 12<br>08529 Plauen<br>Deutschland</p><p>Telefon: +49 (0) 151 59156639<br>E-Mail: Anfrage@Michael-Gahn.de<br>USt-IdNr.: DE288143343<br>Steuernummer: 223/222/02451</p><p>Lizenz: GPL-2.0-or-later</p></section><?php}
 else{$doctor=MGD_WordPress_MCP_Doctor::summary();?><div class="mgd-wpmcp-features"><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">↗</div><h3>KI-Agent verbinden</h3><p><?php echo esc_html($doctor['passed'].' von '.$doctor['total'].' Checks bereit');?></p><a href="<?php echo esc_url(add_query_arg('tab','help',$base));?>">Verbindung prüfen →</a></article><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">AI</div><h3>Start-Prompt</h3><p>Gib deinem Agenten sofort den richtigen Projektkontext.</p><a href="<?php echo esc_url(add_query_arg('tab','start-prompt',$base));?>">Prompt kopieren →</a></article><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">▱</div><h3>Builder & Plugins</h3><p><?php echo esc_html($env['builder']['label']);?> erkannt.</p><a href="<?php echo esc_url(add_query_arg('tab','wizard',$base));?>">Einrichtung →</a></article><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">◇</div><h3>Sicher & kontrollierbar</h3><p>Profile und feingranulare Freigaben.</p><a href="<?php echo esc_url(add_query_arg('tab','settings',$base));?>">Freigaben →</a></article></div><div class="mgd-wpmcp-grid"><section class="mgd-wpmcp-card"><h2>Dein MCP-Endpunkt</h2><div class="mgd-wpmcp-endpoint"><code><?php echo esc_html(MGD_WordPress_MCP::adapter_endpoint_url());?></code></div></section><section class="mgd-wpmcp-card"><h2>Systemstatus</h2><ul class="mgd-wpmcp-status-list"><li><span>WordPress</span><strong><?php echo esc_html(get_bloginfo('version'));?></strong></li><li><span>PHP</span><strong><?php echo esc_html(PHP_VERSION);?></strong></li><li><span>MCP Adapter</span><strong><?php echo class_exists('\\WP\\MCP\\Core\\McpAdapter')?'✓':'✕';?></strong></li><li><span>HTTPS</span><strong><?php echo is_ssl()?'✓':'⚠';?></strong></li><li><span>Builder</span><strong><?php echo esc_html($env['builder']['label']);?></strong></li></ul></section></div><?php} ?><footer class="mgd-wpmcp-footer"><span>MGD WordPress MCP v<?php echo esc_html(MGD_WPMCP_VERSION);?> · Michael Gahn DESIGN</span><span>Privacy by Default · UI-Ressourcen lokal</span></footer></div><?php }
